import { z } from 'zod';
import { DifficultySchema } from './preferences.js';

/* ===========================================================================
 * Practice: SOC Investigation Simulator (5.1) and CTF-style challenges (5.2).
 * Generated by AI (or deterministic fixtures offline). Ground truth, hints and
 * answer keys stay on the server until the learner submits / solves / gives up.
 * ======================================================================== */

export const LogSourceSchema = z.enum(['windows-security', 'sysmon', 'firewall', 'proxy', 'dns', 'linux-auth', 'edr', 'email']);

export const LogFieldSchema = z.object({
  key: z.string().min(1).max(60),
  value: z.string().max(400),
});

/** One synthetic log line. `id` is stable within a case (e.g. "e07"). */
export const LogEventSchema = z.object({
  id: z.string().min(1).max(20),
  timestamp: z.string().min(1).max(40),
  source: LogSourceSchema,
  host: z.string().max(120).default(''),
  eventId: z.string().max(40).default(''),
  user: z.string().max(120).default(''),
  message: z.string().min(1).max(600),
  fields: z.array(LogFieldSchema).max(12).default([]),
});

export const IocTypeSchema = z.enum(['ip', 'domain', 'url', 'hash', 'user', 'process', 'file', 'registry', 'email', 'other']);

export const IocSchema = z.object({ type: IocTypeSchema, value: z.string().min(1).max(400) });

export const TechniqueSchema = z.object({
  id: z.string().regex(/^T\d{4}(\.\d{3})?$/, 'MITRE ATT&CK technique id like T1110 or T1059.001'),
  name: z.string().max(160).default(''),
});

export const HintSchema = z.object({ text: z.string().min(1).max(600), cost: z.number().int().min(0).max(25).default(5) });

export const InvestigationGroundTruthSchema = z.object({
  summary: z.string().min(1).max(3000),
  /** Attack steps in chronological order; each references the log line that shows it. */
  timeline: z.array(z.object({ eventId: z.string().min(1).max(20), description: z.string().min(1).max(400) })).min(2).max(25),
  iocs: z.array(IocSchema).min(1).max(20),
  techniques: z.array(TechniqueSchema).min(1).max(12),
  response: z.array(z.string().min(1).max(400)).max(10).default([]),
});

/** What the model must return for a case. */
export const GeneratedInvestigationSchema = z.object({
  title: z.string().min(1).max(160),
  brief: z.string().min(1).max(2500),
  objectives: z.array(z.string().min(1).max(300)).max(6).default([]),
  difficulty: DifficultySchema.default('intermediate'),
  events: z.array(LogEventSchema).min(12).max(100),
  groundTruth: InvestigationGroundTruthSchema,
  hints: z.array(HintSchema).min(1).max(6),
  rubric: z.array(z.string().min(1).max(300)).min(1).max(8),
});

export const HypothesisSchema = z.object({
  id: z.string().min(1).max(40),
  text: z.string().min(1).max(1000),
  status: z.enum(['open', 'supported', 'refuted']).default('open'),
});

/** The learner's working state: evidence board, timeline and hypotheses. */
export const InvestigationWorkspaceSchema = z.object({
  evidence: z.array(z.object({ eventId: z.string().min(1).max(20), note: z.string().max(1000).default('') })).max(100).default([]),
  timeline: z.array(z.string().min(1).max(20)).max(100).default([]),
  hypotheses: z.array(HypothesisSchema).max(20).default([]),
});

export const InvestigationReportSchema = z.object({
  /** What happened, in the learner's words. */
  summary: z.string().trim().min(1, 'Describe what happened').max(8000),
  iocs: z.array(z.string().trim().min(1).max(400)).max(40).default([]),
  techniques: z.array(z.string().trim().min(1).max(60)).max(20).default([]),
  /** Ordered event ids (defaults to the saved timeline). */
  timeline: z.array(z.string().min(1).max(20)).max(100).optional(),
  response: z.string().trim().max(4000).default(''),
});

export const GeneratePracticeSchema = z.object({
  difficulty: DifficultySchema.optional(),
  focus: z.string().trim().max(300).optional(),
});

/* ------------------------------------------------------------- challenges */

export const ChallengeKindSchema = z.enum(['log-hunt', 'command', 'ioc']);

export const GeneratedChallengeSchema = z
  .object({
    id: z.string().min(1).max(40),
    kind: ChallengeKindSchema,
    title: z.string().min(1).max(160),
    prompt: z.string().min(1).max(1500),
    /** A command / query / snippet shown as plain text. It is never executed. */
    snippet: z.string().max(2000).default(''),
    answerFormat: z.enum(['value', 'choice']),
    options: z.array(z.string().min(1).max(300)).max(6).default([]),
    correctOptionIndex: z.number().int().nonnegative().optional(),
    /** Accepted values for `value` answers (first one is shown after solving). */
    answers: z.array(z.string().min(1).max(300)).max(8).default([]),
    explanation: z.string().min(1).max(2000),
    points: z.number().int().min(5).max(100).default(20),
    hints: z.array(HintSchema).max(3).default([]),
  })
  .superRefine((c, ctx) => {
    if (c.answerFormat === 'choice') {
      if (c.options.length < 2) ctx.addIssue({ code: 'custom', message: 'Choice challenges need at least 2 options', path: ['options'] });
      if (c.correctOptionIndex === undefined || c.correctOptionIndex >= c.options.length) {
        ctx.addIssue({ code: 'custom', message: 'Missing or invalid correct option', path: ['correctOptionIndex'] });
      }
    } else if (!c.answers.length) {
      ctx.addIssue({ code: 'custom', message: 'Value challenges need at least one accepted answer', path: ['answers'] });
    }
  });

export const GeneratedChallengeSetSchema = z.object({
  title: z.string().min(1).max(160),
  description: z.string().max(1500).default(''),
  difficulty: DifficultySchema.default('intermediate'),
  /** Fixture dataset that log-hunt answers must come from. */
  dataset: z.array(LogEventSchema).min(5).max(80),
  challenges: z.array(GeneratedChallengeSchema).min(1).max(12),
});

export const ChallengeAttemptSchema = z
  .object({
    answer: z.string().trim().max(400).optional(),
    optionIndex: z.number().int().min(0).max(5).optional(),
  })
  .refine((v) => (v.answer !== undefined && v.answer.length > 0) || v.optionIndex !== undefined, { message: 'Give an answer' });

export type LogSource = z.infer<typeof LogSourceSchema>;
export type LogEvent = z.infer<typeof LogEventSchema>;
export type Ioc = z.infer<typeof IocSchema>;
export type Technique = z.infer<typeof TechniqueSchema>;
export type Hint = z.infer<typeof HintSchema>;
export type InvestigationGroundTruth = z.infer<typeof InvestigationGroundTruthSchema>;
export type GeneratedInvestigation = z.infer<typeof GeneratedInvestigationSchema>;
export type InvestigationWorkspace = z.infer<typeof InvestigationWorkspaceSchema>;
export type InvestigationReport = z.infer<typeof InvestigationReportSchema>;
export type Hypothesis = z.infer<typeof HypothesisSchema>;
export type ChallengeKind = z.infer<typeof ChallengeKindSchema>;
export type GeneratedChallenge = z.infer<typeof GeneratedChallengeSchema>;
export type GeneratedChallengeSet = z.infer<typeof GeneratedChallengeSetSchema>;
export type ChallengeAttemptInput = z.infer<typeof ChallengeAttemptSchema>;

/* --------------------------------------------------------- response shapes */

export interface ScorePart {
  score: number;
  max: number;
}

export interface InvestigationResult {
  score: number;
  maxScore: number;
  hintPenalty: number;
  iocs: ScorePart & { matched: string[]; missed: string[]; extra: string[] };
  techniques: ScorePart & { matched: string[]; partial: string[]; missed: string[]; extra: string[] };
  timeline: ScorePart & { found: number; total: number; orderAccuracy: number; noise: string[] };
  report: ScorePart & { feedback: string; covered: string[]; missing: string[]; gradedBy: 'ai' | 'rules' };
  submittedAt: string;
}

/** An investigation as the client sees it. `groundTruth` and `result` only after submission. */
export interface PublicInvestigation {
  _id: string;
  lessonId: string;
  projectId: string;
  title: string;
  brief: string;
  objectives: string[];
  difficulty: string;
  events: LogEvent[];
  hintCount: number;
  revealedHints: Hint[];
  hintPenalty: number;
  workspace: InvestigationWorkspace;
  status: 'open' | 'submitted';
  report: InvestigationReport | null;
  result: InvestigationResult | null;
  groundTruth: InvestigationGroundTruth | null;
  createdAt: string;
  updatedAt: string;
}

export interface ChallengeProgress {
  attempts: number;
  solved: boolean;
  revealed: boolean;
  hintsUsed: number;
  score: number;
}

export interface PublicChallenge {
  id: string;
  kind: ChallengeKind;
  title: string;
  prompt: string;
  snippet: string;
  answerFormat: 'value' | 'choice';
  options: string[];
  points: number;
  hintCount: number;
  revealedHints: Hint[];
  maxAttempts: number;
  progress: ChallengeProgress;
  /** Only once solved or revealed. */
  solution: { answer: string; explanation: string } | null;
}

export interface PublicChallengeSet {
  _id: string;
  lessonId: string;
  projectId: string;
  title: string;
  description: string;
  difficulty: string;
  dataset: LogEvent[];
  challenges: PublicChallenge[];
  score: number;
  maxScore: number;
  createdAt: string;
  updatedAt: string;
}

/* ===========================================================================
 * Deterministic matching and scoring (shared so the UI can explain it).
 * ======================================================================== */

export const CHALLENGE_MAX_ATTEMPTS = 5;
/** Score weights for an investigation (sum = 100). */
export const INVESTIGATION_WEIGHTS = { iocs: 30, techniques: 20, timeline: 20, report: 30 } as const;

/**
 * Normalises an indicator or answer for comparison: case, whitespace, quotes,
 * defanged forms (hxxp, [.], (dot)), trailing slashes / dots and path separators.
 */
export function normalizeValue(value: string): string {
  return value
    .normalize('NFKC')
    .trim()
    .toLowerCase()
    .replace(/^["'`<(\[]+|["'`>)\]]+$/g, '')
    .replace(/\[\.\]|\(\.\)|\{\.\}|\[dot\]|\(dot\)/g, '.')
    .replace(/\[:\]/g, ':')
    .replace(/^hxxp(s?):/, 'http$1:')
    .replace(/\\+/g, '\\')
    .replace(/\s+/g, ' ')
    .replace(/[/.]+$/, '')
    .trim();
}

const basename = (v: string) => v.split(/[\\/]/).pop() ?? v;
const stripScheme = (v: string) => v.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '');

/** True when a learner value names the same indicator (full path or just the file name, with or without URL scheme). */
export function valuesMatch(expected: string, given: string): boolean {
  const a = normalizeValue(expected);
  const b = normalizeValue(given);
  if (!a || !b) return false;
  if (a === b) return true;
  if (stripScheme(a) === stripScheme(b)) return true;
  // "C:\Windows\Temp\evil.exe" vs "evil.exe": accept a matching file name (at least 5 chars to avoid "a.b").
  if (/[\\/]/.test(a) || /[\\/]/.test(b)) {
    const ba = basename(a);
    const bb = basename(b);
    if (ba.length >= 5 && ba === bb) return true;
  }
  return false;
}

/** Splits a free-text list ("1.2.3.4, evil.com\nT1110") into items. */
export function parseList(text: string): string[] {
  return [...new Set(text.split(/[\n,;]+/).map((s) => s.trim()).filter(Boolean))];
}

/** Canonical ATT&CK id ("t1059.001 " → "T1059.001"), or null. */
export function normalizeTechnique(value: string): string | null {
  const m = value.trim().toUpperCase().match(/T\d{4}(?:\.\d{3})?/);
  return m ? m[0] : null;
}

const round = (n: number) => Math.round(n * 10) / 10;

export function scoreIocs(expected: Ioc[], given: string[], max: number = INVESTIGATION_WEIGHTS.iocs) {
  const used = new Set<number>();
  const matched: string[] = [];
  const extra: string[] = [];
  for (const g of given) {
    const i = expected.findIndex((e, idx) => !used.has(idx) && valuesMatch(e.value, g));
    if (i >= 0) {
      used.add(i);
      matched.push(expected[i].value);
    } else if (!expected.some((e) => valuesMatch(e.value, g))) {
      extra.push(g);
    }
  }
  const missed = expected.filter((_, i) => !used.has(i)).map((e) => e.value);
  // Each wrong indicator costs a little, so listing everything is not a winning strategy.
  const raw = expected.length ? (matched.length / expected.length) * max : 0;
  const penalty = Math.min(max * 0.3, extra.length * (max / Math.max(expected.length, 1)) * 0.25);
  return { score: round(Math.max(0, raw - penalty)), max, matched, missed, extra };
}

export function scoreTechniques(expected: Technique[], given: string[], max: number = INVESTIGATION_WEIGHTS.techniques) {
  const want = [...new Set(expected.map((t) => t.id.toUpperCase()))];
  const got = [...new Set(given.map(normalizeTechnique).filter((t): t is string => Boolean(t)))];
  const matched: string[] = [];
  const partial: string[] = [];
  const left = new Set(got);
  for (const id of want) {
    if (left.has(id)) {
      matched.push(id);
      left.delete(id);
      continue;
    }
    // Parent / sub-technique of the right technique: half credit.
    const parent = id.split('.')[0];
    const near = [...left].find((g) => g.split('.')[0] === parent);
    if (near) {
      partial.push(id);
      left.delete(near);
    }
  }
  const missed = want.filter((id) => !matched.includes(id) && !partial.includes(id));
  const extra = [...left];
  const raw = want.length ? ((matched.length + partial.length * 0.5) / want.length) * max : 0;
  const penalty = Math.min(max * 0.3, extra.length * (max / Math.max(want.length, 1)) * 0.25);
  return { score: round(Math.max(0, raw - penalty)), max, matched, partial, missed, extra };
}

/**
 * Timeline: 60% for finding the attack events, 40% for putting the found ones in
 * the right relative order (pairwise). Benign events in the timeline cost a little.
 */
export function scoreTimeline(truth: string[], given: string[], max: number = INVESTIGATION_WEIGHTS.timeline) {
  const truthSet = new Set(truth);
  const ordered = [...new Set(given)];
  const found = ordered.filter((id) => truthSet.has(id));
  const noise = ordered.filter((id) => !truthSet.has(id));
  const rank = new Map(truth.map((id, i) => [id, i]));
  let pairs = 0;
  let good = 0;
  for (let i = 0; i < found.length; i++) {
    for (let j = i + 1; j < found.length; j++) {
      pairs++;
      if (rank.get(found[i])! < rank.get(found[j])!) good++;
    }
  }
  const coverage = truth.length ? found.length / truth.length : 0;
  const orderAccuracy = pairs ? good / pairs : found.length === 1 ? 1 : 0;
  const raw = max * (0.6 * coverage + 0.4 * orderAccuracy * coverage);
  const penalty = Math.min(max * 0.25, noise.length * max * 0.03);
  return { score: round(Math.max(0, raw - penalty)), max, found: found.length, total: truth.length, orderAccuracy: Math.round(orderAccuracy * 100) / 100, noise };
}

const STOP = new Set(['the', 'and', 'that', 'this', 'with', 'from', 'into', 'are', 'was', 'were', 'for', 'have', 'has', 'not', 'but', 'you', 'your', 'can', 'will', 'its', 'which', 'when', 'what', 'their', 'they', 'then', 'than', 'also', 'more', 'such', 'should', 'would', 'been', 'after', 'before', 'using', 'used']);
const words = (s: string) => new Set((s.toLowerCase().match(/[a-z0-9]{3,}/g) ?? []).filter((w) => !STOP.has(w)));

/** Deterministic report check: which rubric points share most of their significant words with the report. */
export function rubricCoverage(points: string[], text: string) {
  const answer = words(text);
  const covered = points.filter((p) => {
    const w = [...words(p)];
    return w.length > 0 && w.filter((x) => answer.has(x)).length / w.length >= 0.5;
  });
  return { ratio: points.length ? covered.length / points.length : 0, covered, missing: points.filter((p) => !covered.includes(p)) };
}

/** Points for a solved challenge: minus hint costs and 10% per earlier wrong attempt, never below 25%. */
export function challengePoints(points: number, wrongAttempts: number, hintCost: number): number {
  const afterAttempts = points * Math.max(0.25, 1 - 0.1 * wrongAttempts);
  return Math.max(Math.round(points * 0.1), Math.round(afterAttempts - hintCost));
}

/** Compares a challenge answer with the accepted values (exact after normalisation, or same file name). */
export function answerMatches(accepted: string[], given: string): boolean {
  return accepted.some((a) => valuesMatch(a, given) || normalizeValue(a).replace(/\s+/g, '') === normalizeValue(given).replace(/\s+/g, ''));
}
